function validate([n, a, b, c]) {
  if (![n, a, b, c].every(v => Number.isInteger(v) && v >= 1 && v <= 1000000000)) return 'n, a, b and c are whole numbers from 1 to 10^9.';
  if (BigInt(a) * BigInt(b) * BigInt(c) > 10n ** 18n) return 'a * b * c must be at most 10^18.';
  const gcd = (x, y) => { while (y !== 0n) { [x, y] = [y, x % y]; } return x; };
  const lcm = (x, y) => x / gcd(x, y) * y;
  const list = [BigInt(a), BigInt(b), BigInt(c)];
  let found = 0n;
  for (let mask = 1; mask < 8; mask++) {
    let multiple = 1n, size = 0;
    list.forEach((v, i) => { if ((mask >> i) & 1) { multiple = lcm(multiple, v); size++; } });
    found += (size % 2 === 1 ? 1n : -1n) * (2000000000n / multiple);
  }
  if (found < BigInt(n)) return 'The answer must be at most 2 * 10^9; try a smaller n.';
  return null;
}

