function nthUglyNumber(n, a, b, c) {
  const limit = 2e9;
  const gcd = (x, y) => (y === 0 ? x : gcd(y, x % y));
  const lcm = (x, y) => Math.min((x / gcd(x, y)) * y, limit + 1);
  const ab = lcm(a, b);
  const bc = lcm(b, c);
  const ac = lcm(a, c);
  const abc = lcm(ab, c);
  const count = (x) =>
    Math.floor(x / a) + Math.floor(x / b) + Math.floor(x / c) -
    Math.floor(x / ab) - Math.floor(x / bc) - Math.floor(x / ac) +
    Math.floor(x / abc);

  let left = 1;
  let right = limit;
  while (left < right) {
    const mid = Math.floor((left + right) / 2);
    if (count(mid) >= n) {
      right = mid;
    } else {
      left = mid + 1;
    }
  }
  return left;
}

