function nthUglyNumber(n, a, b, c) {
  const gcd = (x, y) => { while (y !== 0n) { [x, y] = [y, x % y]; } return x; };
  const lcm = (x, y) => x / gcd(x, y) * y;
  const values = [BigInt(a), BigInt(b), BigInt(c)];
  const period = lcm(lcm(values[0], values[1]), values[2]);
  if (period <= 1000000n) {
    // Ugly numbers repeat every lcm(a, b, c): list one period by trial division, then jump whole periods.
    const p = Number(period);
    const inPeriod = [];
    for (let x = 1; x <= p; x++) if (x % a === 0 || x % b === 0 || x % c === 0) inPeriod.push(x);
    return Math.floor((n - 1) / inPeriod.length) * p + inPeriod[(n - 1) % inPeriod.length];
  }
  // A long period: count exactly with BigInt over every non-empty subset of {a, b, c},
  // then build the largest value with fewer than n ugly numbers one bit at a time.
  const terms = [];
  for (let mask = 1; mask < 8; mask++) {
    let multiple = 1n, size = 0;
    values.forEach((v, i) => { if ((mask >> i) & 1) { multiple = lcm(multiple, v); size++; } });
    terms.push([multiple, size % 2 === 1 ? 1n : -1n]);
  }
  const countUpTo = (x) => terms.reduce((sum, [multiple, sign]) => sum + sign * (x / multiple), 0n);
  let below = 0n;
  for (let bit = 31n; bit >= 0n; bit--) if (countUpTo(below + (1n << bit)) < BigInt(n)) below += 1n << bit;
  return Number(below + 1n);
}

