function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const gcd = (x, y) => { while (y !== 0n) { [x, y] = [y, x % y]; } return x; };
  const lcm = (x, y) => x / gcd(x, y) * y;
  // How many ugly numbers are at most x (exact, with BigInt).
  const countUpTo = (x, list) => {
    let total = 0n;
    for (let mask = 1; mask < 8; mask++) {
      let multiple = 1n, size = 0;
      list.forEach((v, i) => { if ((mask >> i) & 1) { multiple = lcm(multiple, BigInt(v)); size++; } });
      total += (size % 2 === 1 ? 1n : -1n) * (x / multiple);
    }
    return total;
  };
  if (size !== 'large') {
    const top = rand() < 0.3 ? 4 : 20;
    return [int(1, 30), int(1, top), int(1, top), int(1, top)];
  }
  // Mix tiny divisors, huge ones, log-spread ones and divisors that are multiples of each other.
  const pick = () => {
    const style = int(0, 3);
    if (style === 0) return int(1, 100);
    if (style === 1) return int(900000000, 1000000000);
    if (style === 2) return Math.floor(Math.pow(10, rand() * 9));
    return int(1, 1000) * int(1, 1000);
  };
  for (;;) {
    const list = [pick(), pick(), pick()];
    if (rand() < 0.2) list[1] = list[0] * int(1, 5);
    if (list.some(v => v < 1 || v > 1000000000)) continue;
    if (BigInt(list[0]) * BigInt(list[1]) * BigInt(list[2]) > 10n ** 18n) continue;
    const most = countUpTo(2000000000n, list);
    const cap = Number(most < 1000000000n ? most : 1000000000n);
    const n = rand() < 0.3 ? cap : int(1, cap);
    return [n, ...list];
  }
}
